import{t as e}from"./utils-COoNfFoj.js";var t={slug:`brian-jung`,influencerName:`Brian Jung`,influencerHandle:`@Jungernaut`,influencerAvatarUrl:`${e}/brian-jung-avatar.jpg`,heroDescription:`My audience splits roughly two ways: serious crypto traders who already do morning research and want to compress an hour into five minutes, and aspiring traders who don't know *what* to research and need a framework. This tool serves both. The dashboard's structure is itself a teachable framework, so even viewers who don't use Perplexity Computer walk away with a clearer mental model of what professional crypto research looks like.`,assetTitle:`Strait of Hormuz Trading Dashboard`,screenshotUrl:`${e}/brian-jung.png`,remixUrl:`https://www.perplexity.ai/computer/a/hormuz-risk-terminal-Pp4TtZ6WQ96zjHIWLt40ZQ`,promptTitle:`Try Brian's Prompt`,promptText:`Create a real-time dashboard monitoring the Strait of Hormuz situation poll news, tweets, and official press releases Also, provide me concise summaries of key developments and give a short directional bias on if I should long or short oil And also, I'm trading Bitcoin, so I want to know if I should be longing or shorting Bitcoin based on what's going on at the strait. Make the summaries easy to understand and actionable, and also make sure you backtest this dashboard logic on the last one to two months of data, just so I know how credible this tool is going to be. I will I want this to be in a dark mode I want this to look aesthetically good and easy, and I want this to genuinely be a tool that I would use in order to help me make money in my investments.`};export{t as default};
